//! Low-level FFI bindings to the C ABI shim over NVIDIA's header-only
//! `cudnn-frontend` (Graph API).
//!
//! These bindings are generated by `bindgen` from `csrc/cudnn_fe_shim.h` at
//! build time. They are raw and unsafe; prefer the safe `cudnn-frontend` crate.
//!
//! cuDNN symbols are resolved at runtime via `dlopen` (the shim is compiled with
//! `NV_CUDNN_FRONTEND_USE_DYNAMIC_LOADING`), so no link-time `-lcudnn` is needed.
#![allow(non_upper_case_globals)]
#![allow(non_camel_case_types)]
#![allow(non_snake_case)]
#![allow(clippy::all)]

include!(concat!(env!("OUT_DIR"), "/bindings.rs"));
